/**
 * Converts a git branch name to a safe filename by replacing all forward-slash
 * characters with dashes and appending the `.txt` extension.
 * For example, "release/10.0" becomes "release-10.0.txt".
 */
export function branchToFilename (branch: string): string {
  return `${branch.split('/').join('-')}.txt`
}

/**
 * Reads all `.txt` files in the given directory and collects their non-empty,
 * non-comment lines as changeset IDs. Returns an empty Set if the directory
 * does not exist.
 */
export function readReleased (dir: string): Set<string> {
  const ids = new Set<string>()
  if (!fs.existsSync(dir)) return ids
  for (const entry of fs.readdirSync(dir)) {
    if (!entry.endsWith('.txt')) continue
    const content = fs.readFileSync(path.join(dir, entry), 'utf8')
    for (const line of content.split('\n')) {
      const trimmed = line.trim()
      if (trimmed === '' || trimmed.startsWith('#')) continue
      ids.add(trimmed)
    }
  }
  return ids
}

/**
 * Appends the given changeset IDs to the file corresponding to
 * `branchToFilename(branch)` inside `dir`, deduplicating against IDs already
 * present, then writes the merged, sorted list back (one ID per line, trailing
 * newline). Creates `dir` if needed. No-op when `ids` is empty.
 */
export function appendReleased (dir: string, branch: string, ids: string[]): void {
  if (ids.length === 0) return
  fs.mkdirSync(dir, { recursive: true })
  const filePath = path.join(dir, branchToFilename(branch))
  const merged = new Set<string>(ids)
  if (fs.existsSync(filePath)) {
    const content = fs.readFileSync(filePath, 'utf8')
    for (const line of content.split('\n')) {
      const trimmed = line.trim()
      if (trimmed === '' || trimmed.startsWith('#')) continue
      merged.add(trimmed)
    }
  }
  const sorted = Array.from(merged).sort()
  fs.writeFileSync(filePath, `${sorted.join('\n')}\n`)
}

/**
 * For each `.md` file in `dir` whose basename (without `.md`) is contained in
 * `releasedIds`, renames the file from `<id>.md` to `<id>.md.released`. Returns
 * the list of hidden changesets. If any rename fails, all renames already
 * performed are rolled back and the original error is re-thrown.
 */
export function hideReleased (dir: string, releasedIds: Set<string>): HiddenChangeset[] {
  const hidden: HiddenChangeset[] = []
  try {
    for (const entry of fs.readdirSync(dir)) {
      if (!entry.endsWith('.md')) continue
      const id = entry.slice(0, -'.md'.length)
      if (!releasedIds.has(id)) continue
      const mdPath = path.join(dir, entry)
      const releasedPath = `${mdPath}.released`
      fs.renameSync(mdPath, releasedPath)
      hidden.push({ id, mdPath, releasedPath })
    }
  } catch (err) {
    // Roll back every rename already performed, then re-throw the original error.
    for (const { mdPath, releasedPath } of hidden) {
      fs.renameSync(releasedPath, mdPath)
    }
    throw err
  }
  return hidden
}

/**
