export function restoreHidden (hidden: HiddenChangeset[]): void {
  for (const { mdPath, releasedPath } of hidden) {
    fs.renameSync(releasedPath, mdPath)
  }
}

/**
 * Permanently deletes each `.md.released` file referenced in `hidden`.
 */
export function deleteHidden (hidden: HiddenChangeset[]): void {
  for (const { releasedPath } of hidden) {
    fs.rmSync(releasedPath, { force: true })
  }
}

